  public void fillTiles(final int distance)
  {
    Queue<Coordinate> queue = new LinkedList<>();
    List<Coordinate> newlyFilled = new ArrayList<>();
    Set<Coordinate> visited = new HashSet<>();
    Pa19Helper pa19Helper = new Pa19Helper();
    
    if (sourceCell != null && sourceCell.getCoord() != null) {
      queue.add(sourceCell.getCoord());
      visited.add(sourceCell.getCoord());
    }
    
    int currentDistance = 0;
    while (currentDistance < distance && !queue.isEmpty()) {
      int size = queue.size();
      for (int i = 0; i < size; i++) {
        Coordinate currCoord = queue.poll();
        Cell currCell = getCell()[currCoord.getRow()][currCoord.getCol()];
        if (currCell instanceof FillableCell) {
          FillableCell fCurrCell = (FillableCell) currCell;
          if (fCurrCell.getPipe() != null) {
            for (Direction dir : fCurrCell.getPipe().getConnections()) {
              Coordinate nextCoord = currCoord.add(pa19Helper.getOffset(dir));
              if (nextCoord != null &&
                  nextCoord.getRow() >= 1 && nextCoord.getRow() <= getRows() - 2 &&
                  nextCoord.getCol() >= 1 && nextCoord.getCol() <= getCols() - 2) {
                
                Cell nextCell = getCell()[nextCoord.getRow()][nextCoord.getCol()];
                if (nextCell instanceof FillableCell && !visited.contains(nextCoord)) {
                  Pipe nextPipe = ((FillableCell) nextCell).getPipe();
                  Direction oppositeDir = pa19Helper.getOpposite(dir);
                  if (nextPipe != null && nextPipe.getConnections().contains(oppositeDir)) {
                    visited.add(nextCoord);
                    newlyFilled.add(nextCoord);
                    queue.add(nextCoord);
                  }
                }
              }
            }
          }
        }
      }
      currentDistance++;
    }
    
    filledTiles.addAll(newlyFilled);
    prevFilledTiles = newlyFilled.size();
  }

